.guide-panel {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 0.75rem;
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}
.exp-btn {
  width: 100%;
  padding: 0.75rem 1rem;
  background: linear-gradient(135deg, #10b981, #059669);
  color: #fff;
  border: none;
  border-radius: 0.6rem;
  font-size: 0.85rem;
  font-weight: 700;
  cursor: pointer;
  font-family: inherit;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  transition: all 0.2s;
}
.exp-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(16,185,129,0.35);
}
.exp-btn-icon { font-size: 1.2rem; }
.exp-btn-label { font-size: 0.85rem; }

.guide-hint {
  display: flex;
  align-items: flex-start;
  gap: 0.4rem;
  background: #f0f9ff;
  border: 1px solid #bae6fd;
  border-radius: 0.5rem;
  padding: 0.6rem;
  font-size: 0.7rem;
  color: #0369a1;
}
.guide-hint p { margin: 0; }

.exp-active-header {
  display: flex;
  align-items: flex-start;
  gap: 0.6rem;
}
.exp-active-icon { font-size: 1.8rem; }
.exp-active-info {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  flex: 1;
}
.exp-active-name {
  font-weight: 800;
  font-size: 0.85rem;
  color: #1e293b;
}
.exp-active-desc {
  font-size: 0.7rem;
  color: #64748b;
  line-height: 1.4;
}
.exp-active-actions {
  display: flex;
  gap: 0.4rem;
}
.exp-active-actions button {
  flex: 1;
